/* Loading: built-in window.RT_DATA + ad-hoc FileReader (global script).
   No fetch/XHR local reads (decision B). */

interface Window { RT_DATA?: RtData; }

/** Built-in bundle generated by viewer/tools/embed.py (may be absent). */
function builtinData(): RtData | null {
  if (typeof window === "undefined") return null;
  return window.RT_DATA ?? null;
}

/** Read a JSON file object chosen via <input type="file">. */
function readJsonFile(file: File): Promise<unknown> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onerror = () => reject(new Error("파일 읽기 실패"));
    reader.onload = () => {
      try {
        resolve(JSON.parse(String(reader.result)) as unknown);
      } catch (e) {
        reject(new Error("JSON 파싱 실패: " + String(e)));
      }
    };
    reader.readAsText(file);
  });
}

/** Load an ad-hoc run log chosen via <input type="file">. */
function loadLogFile(file: File): Promise<RunLog> {
  return readJsonFile(file).then((doc) => {
    const bad = validateLogForPlayback(doc);
    if (bad) throw new Error(bad);
    return doc as RunLog;
  });
}

/** Load an ad-hoc puzzle.json chosen via <input type="file">. */
function loadPuzzleFile(file: File): Promise<PuzzleData> {
  return readJsonFile(file).then((doc) => doc as PuzzleData);
}
